package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.jobs.*;
import com.lianxibu.site.service.settings.SettingsUpdateService;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.transaction.PlatformTransactionManager;

class SourceAnalysisProofConfigurationTest {
    static final String[] CORE={"site.browser.enabled","site.content.enabled","site.articles.enabled","site.sources.enabled","site.execution.enabled"};
    ApplicationContextRunner context(){return new ApplicationContextRunner().withUserConfiguration(SourceAnalysisProofConfiguration.class,NewsSourcePreparationConfiguration.class,ResultApplicationConfiguration.class,DispatchReadinessConfiguration.class).withBean(DataSource.class,()->mock(DataSource.class)).withBean(PlatformTransactionManager.class,()->mock(PlatformTransactionManager.class));}
    String[] flags(String absent){return java.util.Arrays.stream(CORE).map(n->n+"="+!n.equals(absent)).toArray(String[]::new);}
    @Test void DefaultAndEveryMissingCoreFlagLeaveGraphAndDispatchAbsent(){context().run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(SourceAnalysisProofGraph.class).isEmpty());});for(String absent:CORE)context().withPropertyValues(flags(absent)).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(SourceAnalysisProofGraph.class).isEmpty());assertTrue(c.getBeansOfType(DispatchReadinessService.class).isEmpty());verifyNoInteractions(c.getBean(DataSource.class),c.getBean(PlatformTransactionManager.class));});}
    @Test void ProofReadersRemainWhenCollectorPreparationAndWorkerAreDisabledAndGateIsAbsent(){context().withPropertyValues(flags(null)).withPropertyValues("site.collector.enabled=false","site.execution.preparation.enabled=false","site.execution.worker.enabled=false").run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(SourceAnalysisProofGraph.class).size());assertNotNull(c.getBean(DispatchReadinessService.class));assertFalse(c.containsBean("sourcePlanPreparationCoordinator"));assertFalse(c.containsBean("workerRuntimeCycle"));verifyNoInteractions(c.getBean(DataSource.class),c.getBean(PlatformTransactionManager.class));});}
    @Test void FullPreparationBeansShareExactlyTheOneActualGraphWithoutStartupWork(){context().withBean(SettingsUpdateService.class,()->mock(SettingsUpdateService.class)).withBean(OperationalInputGate.class,()->mock(OperationalInputGate.class)).withPropertyValues(flags(null)).withPropertyValues("site.collector.enabled=true","site.execution.preparation.enabled=true").run(c->{assertNull(c.getStartupFailure());var g=c.getBean(SourceAnalysisProofGraph.class);assertEquals(1,c.getBeansOfType(SourceAnalysisProofGraph.class).size());assertSame(g.parts(),c.getBean(SourceStagePreparationService.class));assertSame(g.dedupProofs(),c.getBean(SourceDedupStageProofService.class));assertSame(g.dedupObserver(),c.getBean(SourceDedupStageAvailabilityService.class));assertSame(g.valueProofs(),c.getBean(SourceValueStageProofService.class));assertSame(g.valueObserver(),c.getBean(SourceValueStageAvailabilityService.class));assertSame(g.handoffs(),c.getBean(SourceValueIntentService.class));assertSame(g.handoffReceipts(),c.getBean(SourceValueIntentReceiptService.class));assertSame(g.finalProofs(),c.getBean(SourceValueFinalProofService.class));assertSame(g.finalArchives(),c.getBean(SourceValueFinalArchiveService.class));assertSame(g.finalReceipts(),c.getBean(SourceValueFinalReceiptService.class));assertSame(g.finalization(),c.getBean(SourceValueFinalizationService.class));assertSame(g.finalObserver(),c.getBean(SourceValueFinalAvailabilityService.class));assertNotNull(c.getBean(SourcePlanPreparationCoordinator.class));verifyNoInteractions(c.getBean(DataSource.class),c.getBean(PlatformTransactionManager.class),c.getBean(SettingsUpdateService.class),c.getBean(OperationalInputGate.class));});}
}
